from fractions import Fraction

def matmul(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]

def show(M):
    for row in M:
        print("  [" + " ".join(f"{str(x):>5}" for x in row) + " ]")

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def invert(label, A, y):
    a, b, c, d = A[0][0], A[0][1], A[1][0], A[1][1]
    det = a * d - b * c
    print(f"{label}: ad - bc = {paren(a)}·{paren(d)} - {paren(b)}·{paren(c)} = {det}")
    if det == 0:
        print("  singular: no inverse")
        return
    inv = [[Fraction(d, det), Fraction(-b, det)], [Fraction(-c, det), Fraction(a, det)]]
    print(f"  swap a and d, negate b and c, divide by {det}:")
    show(inv)
    print(f"  check, A times the inverse: {[[str(x) for x in row] for row in matmul(A, inv)]}")
    x = [inv[0][0] * y[0] + inv[0][1] * y[1], inv[1][0] * y[0] + inv[1][1] * y[1]]
    print(f"  decoded: ({x[0]}, {x[1]})")

k = int(input())
for p in range(k):
    A = [[int(t) for t in input().split()] for i in range(2)]
    y = [int(t) for t in input().split()]
    invert(f"Problem {p + 1}", A, y)

