from fractions import Fraction
import numpy as np

def show(M, n):
    for row in M:
        left = " ".join(f"{str(x):>5}" for x in row[:n])
        right = " ".join(f"{str(x):>5}" for x in row[n:])
        print(f"  [{left} |{right} ]")

def coef(c):
    if c == 1:
        return ""
    return str(c) if c.denominator == 1 else f"({c})"

def name(op):
    if op[0] == "swap":
        return f"R{op[1]} ↔ R{op[2]}"
    if op[0] == "scale":
        return f"R{op[1]} → {coef(op[2])}R{op[1]}"
    i, j, c = op[1], op[2], op[3]
    sign = "-" if c < 0 else "+"
    return f"R{i} → R{i} {sign} {coef(abs(c))}R{j}"

def do(M, op, n):
    if op[0] == "swap":
        M[op[1] - 1], M[op[2] - 1] = M[op[2] - 1], M[op[1] - 1]
    elif op[0] == "scale":
        M[op[1] - 1] = [op[2] * x for x in M[op[1] - 1]]
    else:
        i, j, c = op[1] - 1, op[2] - 1, op[3]
        M[i] = [M[i][k] + c * M[j][k] for k in range(len(M[i]))]
    print(name(op))
    show(M, n)

def inverse(A):
    n = len(A)
    M = [A[i] + [Fraction(1 if i == j else 0) for j in range(n)] for i in range(n)]
    show(M, n)
    r = 0
    for c in range(n):
        p = r
        while p < n and M[p][c] == 0:
            p += 1
        if p == n:
            continue
        if p != r:
            do(M, ("swap", r + 1, p + 1), n)
        if M[r][c] != 1:
            do(M, ("scale", r + 1, 1 / M[r][c]), n)
        for i in range(n):
            if i != r and M[i][c] != 0:
                do(M, ("replace", i + 1, r + 1, -M[i][c]), n)
        r += 1
    if r < n:
        return None
    return [row[n:] for row in M]

def run(label, rows):
    A = [[Fraction(x) for x in row] for row in rows]
    print(label)
    inv = inverse(A)
    if inv is None:
        print("  a column of A has no pivot: singular, no inverse")
        return
    print("  the right half is the inverse")
    floats = [[float(x) for x in row] for row in inv]
    print(f"  numpy agrees: {np.allclose(np.linalg.inv(rows), floats)}")

run("Case 1 · two by two", [[2, 1], [5, 3]])
run("Case 2 · three by three", [[1, 2, 3], [0, 1, 4], [5, 6, 0]])
run("Case 3 · a swap, and fractions", [[0, 1, 1], [1, 0, 1], [1, 1, 0]])
run("Case 4 · singular", [[1, 2, 3], [2, 4, 6], [1, 0, 1]])
run("Case 5 · the gift boxes", [[1, 1, 0], [0, 1, 1], [1, 0, 1]])

