from fractions import Fraction


def inverse(A):
    n = len(A)
    M = [A[i] + [Fraction(1 if i == j else 0) for j in range(n)] for i in range(n)]
    r = 0
    for c in range(n):
        p = r
        while p < n and M[p][c] == 0:
            p += 1
        if p == n:
            continue
        M[r], M[p] = M[p], M[r]
        M[r] = [x / M[r][c] for x in M[r]]
        for i in range(n):
            if i != r:
                a = M[i][c]
                M[i] = [M[i][k] - a * M[r][k] for k in range(2 * n)]
        r += 1
    if r < n:
        return None, r
    return [row[n:] for row in M], r

def times(M, x):
    return [sum(M[i][j] * x[j] for j in range(len(x))) for i in range(len(M))]

def text(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def solve(label, A, rights):
    inv, r = inverse(A)
    print(f"{label}: pivots in {r} of {len(A)} columns")
    if inv is None:
        print("  singular: Ax = b has no solution or infinitely many, never exactly one")
        return
    print(f"  invertible, A^-1 = {[[str(x) for x in row] for row in inv]}")
    for b in rights:
        x = times(inv, b)
        print(f"  b = {text(b)}: x = A^-1 b = {text(x)}, Ax = {text(times(A, x))}")

k = int(input())
for p in range(k):
    n = int(input())
    A = [[Fraction(t) for t in input().split()] for i in range(n)]
    rights = [[Fraction(t) for t in input().split()] for j in range(int(input()))]
    solve(f"Problem {p + 1}", A, rights)
